import json
from taf.cloud.cbam.provider import CbamProvider


class CbamConnection(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    DEFAULT_VIM_INFO_TYPE = 'OPENSTACK_V2_INFO'
    DEFAULT_CBAM_VERSION = 'cbam18_0'

    def __init__(self,
                 ip,
                 client_id,
                 client_secret,
                 verify=False,
                 version=DEFAULT_CBAM_VERSION,
                 vnfm_api_version=None):
        """
        Connect and authorize to CBAM.
        :raises VersionNotSupported if version of CBAM is not supported.
        :raises VnfmApiNotSupported if vnfm_api_version was specified and it is not supported.

        :param ip: ip address of CBAM
        :param client_id: client identifier
        :param client_secret: client secret key
        :param verify: boolean or path to directory containing certificate. If
                       False then SSL certificate will be ignored.
        :param version: CBAM version identifier in the form "cbamXY_Z",
                        e.g.: "cbam18_0"
        :param vnfm_api_version: VNFM API version identifier in the form
                                 "X.Y", e.g.: "3.1"; if passed, the program
                                 will use the VNFM API in a given version

        """
        self._cbam = CbamProvider.create_cbam(
            ip=ip,
            client_id=client_id,
            client_secret=client_secret,
            version=version,
            verify=verify,
            vnfm_api_version=vnfm_api_version)

    def query_all_vnfs(self):
        """
        Querying provides static information about all the created virtualized network functions (VNFs).

        :return list of dictionaries with information about VNFs if no problem occured,
                a dictionary with problem details otherwise
        """
        result = self._cbam.vnf.query_all_vnfs()
        if isinstance(result, list):
            return [vnf.as_dict() for vnf in result]
        else:
            return result.as_dict()

    def query_one_vnf(self, id):
        """
        Provide static information about exactly one VNF.
        """
        vnf_info = self._cbam.vnf.supported_schemas.VnfInfo(id=id)
        return self._cbam.vnf.query_one(vnf_info=vnf_info).as_dict()

    def create_vnf(self, vnfd_id, name, description):
        """
        Create VNF.
        VNF package has to be available on the catalog server of CBAM VM.

        :param vnfd_id: id of vnf descriptor
        :param name: VNF name, REST API allows to create multiple VNFs with the same name
        :param description: VNF description

        :return: response content
        """
        vnf_info = self._cbam.vnf.supported_schemas.VnfInfo(
            vnfd_id=vnfd_id,
            name=name,
            description=description)
        return self._cbam.vnf.create(vnf_info).as_dict()

    def get_vim_info(self, vnf_instance_name, vim_id):
        """
        Gets the requested vim info resource of a VNF

        :param vnf_instance_name: The name of the Virtualized Network Function (VNF)
        :param vim_id: The identifier of the Virtual Infrastructure Manager (VIM) info
        """
        vnf_info = self._cbam.vnf.supported_schemas.VnfInfo(name=vnf_instance_name)
        vim_info = self._cbam.vnf.supported_schemas.VimInfo(id=vim_id)
        return self._cbam.vnf.get_vim_info(vnf_info, vim_info).as_dict()

    def put_vim_info(self,
                     vnf_instance_name,
                     vim_id,
                     interface_info,
                     vim_info_type=DEFAULT_VIM_INFO_TYPE,
                     **kwargs):
        """
        Updates the specific vim info resource.
        Raises UnsupportedVimInfoType if the type of the VIM info is not
        supported. Currently supported types are: 'OPENSTACK_V2_INFO',
        'OPENSTACK_V3_INFO', 'VMWARE_VCLOUD_INFO', 'OTHER_VIM_INFO'.

        :param vnf_instance_name: The name of the Virtualized Network Function (VNF)
        :param vim_id: The identifier of the Virtual Infrastructure Manager (VIM) info
        :param interface_info: The Keystone endpoint information
        :param vim_info_type: Type of the VIM info structure, defaults to 'OPENSTACK_V2_INFO', raises
        'UnsupportedVimInfoType' exception when the given type isn't supported.
        :param kwargs: Dict with access information for Keystone f.e. password, region, tenant, username
        """
        vnf_info = self._cbam.vnf.supported_schemas.VnfInfo(name=vnf_instance_name)
        vim_info = self._cbam.vnf.supported_schemas.VimInfo(id=vim_id, vim_info_type=vim_info_type)
        return self._cbam.vnf.put_vim_info(vnf_info,
                                           vim_info,
                                           interface_info,
                                           **kwargs).as_dict()

    def instantiate_vnf(self,
                        vnf_instance_name,
                        path_to_parameter_file,
                        password,
                        flavour_id=None):

        """
        Instantiate VNF. VNF should have modified VIM info (put_vim_info) before using this keyword.

        :param vnf_instance_name: The name of the Virtualized Network Function (VNF)
        :param path_to_parameter_file: absolute or relative path to the parameter json file.
                                       The parameters in file should fit the parameters given in put_vim_info.
        :param password: password to vim endpoint
        :param flavour_id: if the parameter is not defined in parameter file,
                           it needs to be given here. Default value is None.

        :return: It returns dictionary with operation execution information which contains id of the operation.
        """

        with open(path_to_parameter_file, 'r+') as fp:
            body_content = json.load(fp)
        return self._cbam.vnf.instantiate(vnf_instance_name,
                                          body_content,
                                          password,
                                          flavour_id).as_dict()

    def modify_vnf(self, vnf_instance_name,
                   path_to_parameter_file):
        """
        Modify VNF.

        :param vnf_instance_name: The name of the Virtualized Network Function (VNF)
        :param path_to_parameter_file: absolute or relative path to json file with params to change.
                                       The file should contain only params to change.
        :return: It returns dictionary with operation execution information which contains id of the operation.
        """
        with open(path_to_parameter_file, 'r+') as fp:
            file_content = fp.read()

        return self._cbam.vnf.modify(vnf_instance_name, file_content).as_dict()

    def terminate_vnf(self,
                      vnf_instance_name,
                      termination_type='GRACEFUL',
                      graceful_termination_timeout=None):
        """
        Terminates an instantiated VNF.

        :param vnf_instance_name: The name of the Virtualized Network Function (VNF)
        :param termination_type: can be "GRACEFUL" or "FORCEFUL", default is "GRACEFUL"
        :param graceful_termination_timeout: can be used if termination_type is "GRACEFUL".
                                             Default value is None.

        :return: It returns dictionary with operation execution information which contains id of the operation.
        """
        if graceful_termination_timeout is not None:
            graceful_termination_timeout = int(graceful_termination_timeout)
        return self._cbam.vnf.terminate(vnf_instance_name,
                                        termination_type,
                                        graceful_termination_timeout).as_dict()

    def delete_vnf(self, vnf_instance_name):
        """
        Delete VNF instance.

        :param vnf_instance_name: The name of the Virtualized Network Function (VNF)

        :return: None if VNF was successfully deleted,
                 dictionary with problem details otherwise
        """
        vnf_info = self._cbam.vnf.supported_schemas.VnfInfo(name=vnf_instance_name)
        result = self._cbam.vnf.delete_vnf(vnf_info)
        if result is not None:
            return result.as_dict()

    def upgrade_vnf(self, vnf_instance_name, vnfd_id):
        """
        Upgrade VNF instance.

        :param vnf_instance_name: The name of the Virtualized Network Function (VNF)
        :param vnfd_id: id of new package to upgrade the VNF

        :return: It returns dictionary with operation execution information which contains id of the operation.
        """
        return self._cbam.vnf.upgrade(vnf_instance_name, vnfd_id).as_dict()

    def get_catalog_info(self):
        """
        Provide information about cbam catalog
        """
        return self._cbam.catalog.get_info()

    def post_catalog_info(self, path):
        """
        Forwards zip package with needed files to create new catalog on cbam

        :param path: Path to the ZIP file with files needed to create new catalog
        """
        with open(path, 'rb') as cbam_catalog_zip:
            return self._cbam.catalog.post_info(cbam_catalog_zip)

    def delete_catalog_info(self, vnfd_id):
        """
        Removes an existing Virtualized Network Function (VNF) template package

        :param vnfd_id: The identifier of the Virtualized Network Function (VNF) template package
        """
        return self._cbam.catalog.delete_info(vnfd_id)

    def get_operation_execution_info(self, operation_id):
        """
        Provide information about single operation execution.

        :param operation_id: The identifier of the operation execution.
        """
        operation_execution = self._cbam.vnf.supported_schemas.OperationExecution(operation_id=operation_id)
        return self._cbam.vnf.get_operation_execution_info(
            operation_execution).as_dict()

    def get_all_operation_execution_info(self, vnf_instance_name=None, all_fields=False):
        """
        Provide information about every operation execution.

        """
        result = self._cbam.vnf.get_all_operation_execution_info(vnf_instance_name=vnf_instance_name,
                                                                 all_fields=all_fields)
        if isinstance(result, list):
            return [operation.as_dict() for operation in result]
        else:
            return result.as_dict()

    def post_custom_operation(self,
                              vnf_instance_name,
                              custom_operation_name,
                              additional_params=None):
        """
        Executes custom operation. Nokia VNFM proprietary extension.

        :param string vnf_instance_name: The name of the Virtualized Network Function (VNF).
        :param string custom_operation_name: The identifier of the custom operation. Possibilities:
                                             'prepare_for_upgrade', 'swm_pre_check', 'upgrade', 'rollback',
                                             'fast_rollback', 'query', 'swm_post_check', 'scale_cleanup'.
        :param dict additional_params: (optional) Additional parameters for custom operation.
                                       Example: {'OAMImage': '5G19_0.135.253'}
        :return: It returns dict with Operation Execution Info.
        """

        vnf_info = self._cbam.vnf.supported_schemas.VnfInfo(name=vnf_instance_name)
        return self._cbam.vnf.post_custom_operation(
            vnf_info, custom_operation_name, additional_params).as_dict()

    def is_connected(self):
        """
        Checks vitality of the current session.

        :return bool: Returns True if session is alive or False if not.
        """
        return self._cbam.is_connected()
